//! S05 clean-view battery over the frozen diverse fixtures: the versioned
//! `reader_clean_profile/v1` rules, the two retained source forms and the
//! typed refusal surface, driven through the frozen `source_package`
//! substrate, `build_projection` and the S04 reading-order index.
//!
//! Every per-fixture unit list below is a handwritten oracle derived from the
//! fixture XML and the pinned profile — never generated by the code under
//! test. Non-claims: bounded to the six self-authored non-legal synthetic
//! fixtures in `fixtures/reader/diverse/`; not corpus coverage, not
//! normalization, not a legal-completeness claim; R1000 stays active. Decoded
//! text is only compared in memory, never printed.

use ln_decode::reader_clean_view::{
    CleanDisposition, CleanErrorKind, CleanRuleProfile, CleanUnit, CleanView,
};
use ln_decode::reader_contract::{
    ReaderFragmentSpan, ReaderRecordIndex, ReaderSemantic, check_fragment_span,
};
use ln_decode::reader_projection::{ReaderProjection, ViewId, build_projection};
use ln_decode::reader_reading_order::ReadingOrderIndex;
use ln_decode::source_package::{Limits, Record, TextSlot, capture};

// ---------------------------------------------------------------- fixtures #

struct Fixture {
    file: &'static str,
    xml: &'static str,
}

const FIXTURES: &[Fixture] = &[
    Fixture {
        file: "text-only.xml",
        xml: include_str!("fixtures/reader/diverse/text-only.xml"),
    },
    Fixture {
        file: "fields-revisions.xml",
        xml: include_str!("fixtures/reader/diverse/fields-revisions.xml"),
    },
    Fixture {
        file: "controls.xml",
        xml: include_str!("fixtures/reader/diverse/controls.xml"),
    },
    Fixture {
        file: "residual-and-tails.xml",
        xml: include_str!("fixtures/reader/diverse/residual-and-tails.xml"),
    },
    Fixture {
        file: "encoding.xml",
        xml: include_str!("fixtures/reader/diverse/encoding.xml"),
    },
    Fixture {
        file: "empty-structure.xml",
        xml: include_str!("fixtures/reader/diverse/empty-structure.xml"),
    },
];

fn fixture(name: &str) -> &'static Fixture {
    FIXTURES
        .iter()
        .find(|entry| entry.file == name)
        .unwrap_or_else(|| panic!("fixture {name} is not declared"))
}

// ------------------------------------------------------------------ helpers #

fn build_fixture(fixture: &Fixture) -> (Vec<Record>, ReaderProjection, ReadingOrderIndex) {
    let package = capture(fixture.xml.as_bytes(), &Limits::default())
        .unwrap_or_else(|error| panic!("{} must capture: {error:?}", fixture.file));
    let records = package.records().to_vec();
    let projection = build_projection(&records)
        .unwrap_or_else(|error| panic!("{} must project: {error:?}", fixture.file));
    let order = ReadingOrderIndex::build(&projection, &records)
        .unwrap_or_else(|errors| panic!("{} must build a reading order: {errors:?}", fixture.file));
    (records, projection, order)
}

fn clean_of(
    fixture: &Fixture,
    records: &[Record],
    projection: &ReaderProjection,
    order: &ReadingOrderIndex,
) -> CleanView {
    CleanView::build(projection, order, records)
        .unwrap_or_else(|error| panic!("{} must build a clean view: {error}", fixture.file))
}

// ------------------------------------------------------------------ profile #

#[test]
fn profile_v1_is_total_with_pinned_rule_ids() {
    let profile = CleanRuleProfile::v1();
    assert_eq!(profile.id(), "reader_clean_profile/v1");
    let expected: &[(&str, ReaderSemantic, CleanDisposition)] = &[
        ("rcv1_body", ReaderSemantic::Body, CleanDisposition::Primary),
        (
            "rcv1_whitespace",
            ReaderSemantic::Whitespace,
            CleanDisposition::Service,
        ),
        (
            "rcv1_field_code",
            ReaderSemantic::FieldCode,
            CleanDisposition::Service,
        ),
        (
            "rcv1_revision_insertion",
            ReaderSemantic::RevisionInsertion,
            CleanDisposition::Primary,
        ),
        (
            "rcv1_revision_deletion",
            ReaderSemantic::RevisionDeletion,
            CleanDisposition::Service,
        ),
        (
            "rcv1_derived_separator",
            ReaderSemantic::DerivedSeparator,
            CleanDisposition::Service,
        ),
        (
            "rcv1_empty",
            ReaderSemantic::Empty,
            CleanDisposition::Dropped,
        ),
    ];
    for (id, class, disposition) in expected {
        let rule = profile.rule_for(*class);
        assert_eq!(rule.id, *id);
        assert_eq!(rule.class, *class);
        assert_eq!(rule.disposition, *disposition);
    }
    assert_eq!(profile.rules().len(), 7);
    // No revision class is silently discarded.
    assert_eq!(
        profile
            .rule_for(ReaderSemantic::RevisionInsertion)
            .disposition,
        CleanDisposition::Primary
    );
    assert_eq!(
        profile
            .rule_for(ReaderSemantic::RevisionDeletion)
            .disposition,
        CleanDisposition::Service
    );
}

// ------------------------------------------------------------------- cases #

#[test]
fn text_only_body_is_primary_and_service_is_empty() {
    let fixture = fixture("text-only.xml");
    let (records, projection, order) = build_fixture(fixture);
    let clean = clean_of(fixture, &records, &projection, &order);
    assert_eq!(clean.profile_id(), "reader_clean_profile/v1");
    assert_eq!(clean.view_ids().len(), 1);
    assert_eq!(clean.units().len(), 1);
    match &clean.units()[0] {
        CleanUnit::Source {
            slot: TextSlot::Text,
            disposition,
            ..
        } => assert_eq!(*disposition, CleanDisposition::Primary),
        other => panic!("text-only must retain one source unit, got {other:?}"),
    }
    assert_eq!(clean.primary_text(), "Только текст");
    assert_eq!(clean.service_text(), "");
    let text = clean
        .view_text(&clean.view_ids()[0])
        .expect("a primary view is a clean surface");
    assert_eq!(text.primary(), "Только текст");
    assert_eq!(text.service(), "");
}

#[test]
fn field_and_revision_classes_keep_source_mapping_and_never_drop() {
    let fixture = fixture("fields-revisions.xml");
    let (records, projection, order) = build_fixture(fixture);
    let clean = clean_of(fixture, &records, &projection, &order);
    assert_eq!(clean.view_ids().len(), 2);
    assert_eq!(clean.units().len(), 3);
    // Classification comes from the projection's segment semantics.
    let semantics: Vec<ReaderSemantic> = projection
        .segments
        .iter()
        .map(|segment| segment.semantic)
        .collect();
    assert_eq!(
        semantics,
        [
            ReaderSemantic::FieldCode,
            ReaderSemantic::RevisionInsertion,
            ReaderSemantic::RevisionDeletion,
        ]
    );
    assert_eq!(
        projection
            .segments
            .iter()
            .map(|segment| segment.view.as_str())
            .collect::<Vec<_>>(),
        ["v0", "v1", "v1"]
    );
    // No revision class is silently discarded and none is dropped.
    assert!(
        clean
            .units()
            .iter()
            .all(|unit| unit.disposition() != CleanDisposition::Dropped)
    );
    assert_eq!(clean.units()[0].disposition(), CleanDisposition::Service);
    assert_eq!(clean.units()[1].disposition(), CleanDisposition::Primary);
    assert_eq!(clean.units()[2].disposition(), CleanDisposition::Service);
    // Each retained unit resolves the §5 source fragment form.
    let record_index = ReaderRecordIndex::new(&records).expect("substrate must index");
    for unit in clean.units() {
        match unit {
            CleanUnit::Source {
                fragment_ref, span, ..
            } => {
                let value = &record_index
                    .text(fragment_ref.as_str())
                    .unwrap_or_else(|| panic!("fragment {} is missing", fragment_ref))
                    .value;
                assert!(check_fragment_span(value, span).is_ok());
            }
            other => panic!("field/revision units must stay retained source, got {other:?}"),
        }
    }
    assert_eq!(clean.primary_text(), "добавлено");
    assert_eq!(clean.service_text(), "HYPERLINK \"target\"удалено");
}

#[test]
fn derived_controls_are_service_without_source_mapping() {
    let fixture = fixture("controls.xml");
    let (records, projection, order) = build_fixture(fixture);
    let clean = clean_of(fixture, &records, &projection, &order);
    assert_eq!(clean.view_ids().len(), 6);
    assert_eq!(clean.units().len(), 17);
    let mut literals: Vec<&str> = Vec::new();
    for unit in clean.units() {
        match unit {
            CleanUnit::Derived {
                kind,
                literal,
                disposition,
                ..
            } => {
                assert_eq!(*disposition, CleanDisposition::Service);
                assert_eq!(*literal, kind.literal());
                literals.push(literal);
            }
            CleanUnit::Source { .. } => {}
            CleanUnit::Dropped { .. } => panic!("controls fixture must not drop a unit"),
        }
    }
    assert_eq!(literals, ["\n", "\n", "\n", "\n", "\t"]);
    assert_eq!(clean.primary_text(), "ABABABABABAB");
    assert_eq!(clean.service_text(), "\n\n\n\n\t");
}

#[test]
fn residual_body_stays_primary_and_whitespace_is_service() {
    let fixture = fixture("residual-and-tails.xml");
    let (records, projection, order) = build_fixture(fixture);
    let clean = clean_of(fixture, &records, &projection, &order);
    assert_eq!(clean.view_ids().len(), 4);
    assert_eq!(clean.units().len(), 6);
    let service: Vec<&CleanUnit> = clean
        .units()
        .iter()
        .filter(|unit| unit.disposition() == CleanDisposition::Service)
        .collect();
    assert_eq!(service.len(), 1);
    assert!(matches!(service[0], CleanUnit::Source { .. }));
    assert_eq!(clean.primary_text(), "BODY-TEXTRUNTAIL-TEXTPTTAIL");
    assert_eq!(clean.service_text(), "   ");
}

#[test]
fn decoded_values_pass_through_verbatim() {
    let fixture = fixture("encoding.xml");
    let (records, projection, order) = build_fixture(fixture);
    let clean = clean_of(fixture, &records, &projection, &order);
    assert_eq!(clean.view_ids().len(), 3);
    assert_eq!(clean.units().len(), 9);
    assert_eq!(clean.primary_text(), "Приветмир!Жe\u{301}😀NBSP:\u{a0}Mu");
    assert_eq!(clean.service_text(), "\t\n");
    assert!(
        clean.primary_text().contains('\u{a0}'),
        "NBSP must survive verbatim"
    );
    assert!(
        clean.primary_text().contains('😀'),
        "an astral char must survive verbatim"
    );
}

#[test]
fn empty_views_own_nothing_and_navigation_is_refused() {
    let fixture = fixture("empty-structure.xml");
    let (records, projection, order) = build_fixture(fixture);
    let clean = clean_of(fixture, &records, &projection, &order);
    assert_eq!(clean.view_ids().len(), 3);
    assert_eq!(clean.units().len(), 1);
    assert_eq!(clean.primary_text(), "X");
    assert_eq!(
        clean
            .view_texts()
            .iter()
            .filter(|text| text.primary().is_empty())
            .count(),
        2
    );
    let navigation = projection
        .views
        .iter()
        .find(|view| !view.kind.is_primary())
        .expect("empty-structure carries navigation views");
    let error = clean
        .view_text(&navigation.id)
        .expect_err("a navigation view must refuse");
    assert_eq!(error.kind(), CleanErrorKind::NotPrimaryView);
    let absent = clean.view_text(&ViewId::new("v-absent"));
    assert_eq!(
        absent.expect_err("an absent view must refuse").kind(),
        CleanErrorKind::NotPrimaryView
    );
}

#[test]
fn every_unit_resolves_one_of_the_two_source_forms() {
    for fixture in FIXTURES {
        let (records, projection, order) = build_fixture(fixture);
        let clean = clean_of(fixture, &records, &projection, &order);
        let record_index = ReaderRecordIndex::new(&records).expect("substrate must index");
        assert_eq!(clean.profile_id(), "reader_clean_profile/v1");
        for unit in clean.units() {
            match unit {
                CleanUnit::Source {
                    fragment_ref, span, ..
                } => {
                    let value = &record_index
                        .text(fragment_ref.as_str())
                        .unwrap_or_else(|| {
                            panic!("{}: fragment {fragment_ref} is missing", fixture.file)
                        })
                        .value;
                    assert!(
                        check_fragment_span(value, span).is_ok(),
                        "{}: a retained span must validate",
                        fixture.file
                    );
                }
                CleanUnit::Derived { kind, literal, .. } => {
                    assert_eq!(*literal, kind.literal(), "{}", fixture.file);
                }
                CleanUnit::Dropped { rule_id, .. } => {
                    assert!(!rule_id.is_empty(), "{}", fixture.file);
                }
            }
        }
    }
}

#[test]
fn malformed_projection_and_substrate_are_refused_typed() {
    let fixture = fixture("text-only.xml");
    let (records, projection, order) = build_fixture(fixture);

    // Span drift: the retained span leaves the decoded fragment.
    let mut tampered = projection.clone();
    let fragment = tampered.segments[0]
        .fragment_ref
        .clone()
        .expect("a source segment names a fragment");
    tampered.segments[0].span = Some(ReaderFragmentSpan::new(fragment, 0, 4096));
    let error = CleanView::build(&tampered, &order, &records).expect_err("span drift must refuse");
    assert_eq!(error.kind(), CleanErrorKind::SpanInvalid);

    // Missing §5 members: no span, no slot.
    let mut tampered = projection.clone();
    tampered.segments[0].span = None;
    assert_eq!(
        CleanView::build(&tampered, &order, &records)
            .expect_err("a missing span must refuse")
            .kind(),
        CleanErrorKind::SourceMappingIncomplete
    );
    let mut tampered = projection.clone();
    tampered.segments[0].slot = None;
    assert_eq!(
        CleanView::build(&tampered, &order, &records)
            .expect_err("a missing slot must refuse")
            .kind(),
        CleanErrorKind::SourceMappingIncomplete
    );

    // A reading-order segment with no projection record.
    let mut tampered = projection.clone();
    tampered.segments.clear();
    assert_eq!(
        CleanView::build(&tampered, &order, &records)
            .expect_err("an unknown segment must refuse")
            .kind(),
        CleanErrorKind::UnknownSegment
    );

    // A primary view the reading-order index does not carry.
    let mut tampered = projection.clone();
    tampered.views[0].id = ViewId::new("v-renamed");
    assert_eq!(
        CleanView::build(&tampered, &order, &records)
            .expect_err("an unknown view must refuse")
            .kind(),
        CleanErrorKind::UnknownView
    );

    // The substrate no longer carries the fragment.
    let fragment_id = projection.segments[0]
        .fragment_ref
        .as_ref()
        .expect("a source segment names a fragment")
        .as_str()
        .to_string();
    let mut reduced = records.clone();
    reduced.retain(|record| !matches!(record, Record::Text(text) if text.id == fragment_id));
    assert_eq!(
        CleanView::build(&projection, &order, &reduced)
            .expect_err("a missing fragment must refuse")
            .kind(),
        CleanErrorKind::SourceMappingIncomplete
    );
}

#[test]
fn rebuild_is_idempotent_and_non_mutating() {
    let fixture = fixture("fields-revisions.xml");
    let (records, projection, order) = build_fixture(fixture);
    let records_before = records.clone();
    let projection_before = projection.clone();
    let first = clean_of(fixture, &records, &projection, &order);
    let second = CleanView::build(&projection, &order, &records)
        .unwrap_or_else(|error| panic!("a rebuild must succeed: {error}"));
    assert_eq!(first, second);
    assert_eq!(records, records_before);
    assert_eq!(projection, projection_before);
}

#[test]
fn empty_semantic_drops_with_rule_id_and_without_a_source_form() {
    let fixture = fixture("text-only.xml");
    let (records, projection, order) = build_fixture(fixture);
    // `build_projection` never emits the `empty` class (an empty fragment is
    // not captured), so the total profile's dropped path is exercised by
    // classifying a segment `empty` directly — the clean view consumes
    // `segment.semantic` as its only classification source.
    let mut classified_empty = projection.clone();
    let anchor = {
        let segment = &mut classified_empty.segments[0];
        segment.semantic = ReaderSemantic::Empty;
        (segment.element_ref.clone(), segment.source_pos)
    };
    let clean = CleanView::build(&classified_empty, &order, &records)
        .unwrap_or_else(|error| panic!("a classified-empty projection must clean: {error}"));
    assert_eq!(clean.units().len(), 1);
    assert_eq!(clean.primary_text(), "");
    assert_eq!(clean.service_text(), "");
    match &clean.units()[0] {
        CleanUnit::Dropped {
            rule_id,
            element_ref,
            source_pos,
            ..
        } => {
            assert_eq!(*rule_id, "rcv1_empty");
            assert_eq!(element_ref, &anchor.0);
            assert_eq!(*source_pos, anchor.1);
        }
        other => panic!("empty must drop with its rule id, got {other:?}"),
    }
}
